THOUGHT: I can see the issue now. Looking at the `FixedRollingArray` class:

1. The constructor initializes `samples` with `width` elements using `arraySeed(padValue, this.width)`
2. In `pushValue`, when a new value is added at the front, the array becomes `width + 1` elements long
3. The bug is in the condition: `if (swap.length > this.width - 1)` - this should be `this.width` because:
   - After adding a new value, the array has `width + 1` elements
   - We need to slice to keep only `width` elements, not `width - 1` elements

Let me create a simple test script to verify this understanding:

```bash
cat <<'EOF' > test_rolling_array.js
// Simple test to verify the FixedRollingArray behavior

function arraySeed(val, length) {
    const a = [];
    for (let i = 0; i < length; i++) {
        a.push(val);
    }
    return a;
}

// Simulating FixedRollingArray with width=3
let width = 3;
let samples = arraySeed("pad", width); // ["pad", "pad", "pad"]

console.log("Initial:", samples);

// Simulating pushValue with new value "new"
let swap = [...samples];
swap.splice(0, 0, "new"); // ["new", "pad", "pad", "pad"]
console.log("After adding new:", swap);

// Current (buggy) logic:
if (swap.length > width - 1) {
    swap = swap.slice(0, width - 1);
    console.log("Buggy slice (width-1):", swap);
} else {
    console.log("No slice applied");
}

// Correct logic should be:
if (swap.length > width) {
    swap = swap.slice(0, width);
    console.log("Correct slice (width):", swap);
}

console.log("Expected result: ['new', 'pad', 'pad']");
EOF
